    "<button class=\"carte-anglais\" data-a=\"salon-public\"><span class=\"ic\">🌍</span><strong>Salons publics</strong><small>Avec d’autres joueurs : réactions toutes faites seulement</small></button></div>":["<button class=\"carte-anglais\" data-a=\"salon-public\"><span class=\"ic\">🌍</span><strong>Public rooms</strong><small>With other players: ready-made reactions only</small></button></div>","<button class=\"carte-anglais\" data-a=\"salon-public\"><span class=\"ic\">🌍</span><strong>Salas públicas</strong><small>Con otros jugadores: solo reacciones predefinidas</small></button></div>","<button class=\"carte-anglais\" data-a=\"salon-public\"><span class=\"ic\">🌍</span><strong>Öffentliche Räume</strong><small>Mit anderen Spielern: nur vorgefertigte Reaktionen</small></button></div>","<button class=\"carte-anglais\" data-a=\"salon-public\"><span class=\"ic\">🌍</span><strong>Stanze pubbliche</strong><small>Con altri giocatori: solo reazioni predefinite</small></button></div>","<button class=\"carte-anglais\" data-a=\"salon-public\"><span class=\"ic\">🌍</span><strong>Salas públicas</strong><small>Com outros jogadores: só reações pré-definidas</small></button></div>"],
